    """
    Implements a regular expression matching algorithm for patterns
    that support literal characters, '.', '*', and '+'. This algorithm
    uses recursion to handle the matching logic.
    """

    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx < len(pattern) and p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
            # Match with or without the preceding element
            return (t_idx < len(text) and 
                    (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.') and 
                    is_match(p_idx, t_idx + 1)) or is_match(p_idx + 2, t_idx)
        if p_idx < len(pattern) and p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '+':
            return (t_idx < len(text) and 
                    (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.') and 
                    (is_match(p_idx, t_idx + 1) or is_match(p_idx + 2, t_idx)))
        if p_idx < len(pattern) and t_idx < len(text):
            return (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.') and is_match(p_idx + 1, t_idx + 1)

        return False

    return is_match(0, 0)

