    """
    Implements a basic regex matching algorithm using recursion and memoization.
    The algorithm supports literal characters, '.' (matching any character),
    '*' (zero or more of the preceding element), and '+' (one or more of 
    the preceding element).
    """

    def is_match(p: str, t: str, memo: dict) -> bool:
