def match(pattern: str, text: str) -> bool:
    """
    Implements a backtracking algorithm for basic regex matching supporting
    literal characters, '.', '*', and '+'. The function recursively checks
    if the pattern can be matched with the text.
    """

    def is_match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(text)

        first_match = i < len(text) and (text[i] == pattern[j] or pattern[j] == '.')

        if j + 1 < len(pattern) and pattern[j + 1] in '*+':
            if pattern[j + 1] == '*':
                return (is_match(i, j + 2) or 
                        (first_match and is_match(i + 1, j)))
            elif pattern[j + 1] == '+':
                return first_match and (is_match(i + 1, j) or is_match(i, j + 2))

        if first_match:
            return is_match(i + 1, j + 1)

        return False

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    This function uses dynamic programming to implement a basic regex matching algorithm.
    It supports literal characters, '.', '*' (zero or more of the preceding element), and
    '+' (one or more of the preceding element).

    The approach is to use a 2D table to store matching results and fill it based on patterns and text.
    """
    m, n = len(text), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    def matches(i, j):
        return i > 0 and (text[i - 1] == pattern[j - 1] or pattern[j - 1] == '.')

    for j in range(1, n + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]
        elif pattern[j - 1] == '+':
            dp[0][j] = j > 1 and dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (matches(i, j - 1) and dp[i - 1][j])
            elif pattern[j - 1] == '+':
                dp[i][j] = matches(i, j - 1) and (dp[i - 1][j] or (i > 1 and dp[i - 1][j - 2]))
            else:
                dp[i][j] = matches(i, j) and dp[i - 1][j - 1]

    return dp[m][n]
